<template><form class="replacement-preview" @submit.prevent="$emit('submit',{replacementPreview:preview})"><h3>{{t('replacementTitle')}}</h3><p>{{t('replacementHelp')}}</p><dl><dt>{{t('version')}}</dt><dd>{{preview.executionVersion}}</dd><dt>{{t('revision')}}</dt><dd>#{{preview.revisionId}} · {{preview.revisionHash}}</dd><dt>{{t('effectiveAt')}}</dt><dd>{{preview.effectiveAt}}</dd><dt>{{t('predecessorOrders')}}</dt><dd>{{preview.sortedOrderIds.join(', ') || t('none')}}</dd><dt>{{t('predecessorReminders')}}</dt><dd>{{preview.sortedReminderIds.join(', ') || t('none')}}</dd></dl><p>{{t('preservePersonal')}}</p><button type="submit" :disabled="disabled">{{t('scheduleReplacement')}}</button><button type="button" @click="$emit('close')">{{t('close')}}</button></form></template>
<script setup>
import {medicationText as t} from '@/utils/medicationExecutionCopy';
defineProps({preview:{type:Object,required:true},disabled:Boolean});defineEmits(['submit','close']);
</script>
<style scoped>.replacement-preview{padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink-950);min-width:0;overflow-wrap:anywhere}.replacement-preview dd{margin:0 0 12px}.replacement-preview button{font:inherit;min-height:44px;max-width:100%;white-space:normal;padding:8px 12px;margin:4px;border:1px solid var(--line);background:var(--paper);color:var(--ink-950);border-radius:8px}.replacement-preview button:focus-visible{outline:3px solid var(--care-600)}@media(max-width:600px){.replacement-preview button{width:100%;margin:4px 0}}</style>
